function countMatchingSubarrays(nums, pattern) {
  const m = pattern.length;
  const lps = new Array(m).fill(0);
  let k = 0;
  for (let i = 1; i < m; i++) {
    while (k > 0 && pattern[i] !== pattern[k]) k = lps[k - 1];
    if (pattern[i] === pattern[k]) k++;
    lps[i] = k;
  }

  let count = 0;
  let matched = 0;
  for (let i = 1; i < nums.length; i++) {
    const step = Math.sign(nums[i] - nums[i - 1]);
    while (matched > 0 && step !== pattern[matched]) matched = lps[matched - 1];
    if (step === pattern[matched]) matched++;
    if (matched === m) {
      count++;
      matched = lps[m - 1];
    }
  }
  return count;
}

brute:
function countMatchingSubarrays(nums, pattern) {
  let total = 0;
  for (let start = 0; start + pattern.length < nums.length; start++) {
    let fits = true;
    for (let k = 0; k < pattern.length; k++) {
      const a = nums[start + k], b = nums[start + k + 1];
      const want = pattern[k];
      if ((want === 1 && !(b > a)) || (want === 0 && b !== a) || (want === -1 && !(b < a))) { fits = false; break; }
    }
    if (fits) total++;
  }
  return total;
}

