function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1800, 2000) : int(2, 12);
  const mode = int(0, 3);
  let nums;
  if (mode === 0) {
    // Few distinct values, so equal neighbours and short runs are common.
    nums = Array.from({ length: n }, () => int(1, 4));
  } else if (mode === 1) {
    // A short block of moves repeated over and over, which gives many overlapping matches.
    const block = Array.from({ length: int(1, 4) }, () => int(-1, 1));
    nums = [int(1, 3) * 10000];
    for (let i = 1; i < n; i++) nums.push(nums[i - 1] + block[i % block.length] * int(1, 3));
  } else if (mode === 2) {
    nums = Array.from({ length: n }, () => int(1, 1e9));
  } else {
    // Mostly flat with rare bumps: long runs of 0 moves stress the failure links.
    nums = Array.from({ length: n }, () => (rand() < 0.05 ? 8 : 7));
  }
  const moves = [];
  for (let i = 1; i < n; i++) moves.push(Math.sign(nums[i] - nums[i - 1]));
  const longest = n - 1;
  const m = size === 'large' && rand() < 0.5 ? int(1, Math.min(longest, 400)) : int(1, Math.min(longest, 6));
  let pattern;
  if (rand() < 0.7) {
    // Copy a real stretch of moves so the pattern occurs at least once.
    const at = int(0, longest - m);
    pattern = moves.slice(at, at + m);
  } else {
    pattern = Array.from({ length: m }, () => int(-1, 1));
  }
  return [nums, pattern];
}
